import sys
from collections import Counter

def is_palindrome(s):
    return s == s[::-1]

def apply_permutation(s, perm):
    return ''.join(s[p-1] for p in perm)

def find_palindrome_permutation(s):
    n = len(s)
    freq = Counter(s)
    odd_count = sum(1 for count in freq.values() if count % 2 == 1)

    if odd_count > 1:
        return [-1]

    left = 0
    right = n - 1
    perm = [0] * n

    for char in sorted(freq.keys(), key=lambda x: (-freq[x], x)):
        count = freq[char]
        while count > 0:
            if left <= right:
                perm[left] = left + 1
                left += 1
                count -= 1
            if left <= right:
                perm[right] = right + 1
                right -= 1
                count -= 1

    return perm

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        s = data[index]
        index += 1
        perm = find_palindrome_permutation(s)
        if perm == [-1]:
            results.append('-1')
        else:
            results.append(' '.join(map(str, perm)))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
